PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL, quota INTEGER NOT NULL DEFAULT 4, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), email TEXT NOT NULL, role TEXT NOT NULL, revoked_at TEXT, UNIQUE(tenant_id,email));
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), tenant_id TEXT NOT NULL REFERENCES tenants(id), expires_at TEXT NOT NULL, revoked_at TEXT);
CREATE TABLE IF NOT EXISTS robots (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), serial TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, lease_until TEXT, created_at TEXT NOT NULL, UNIQUE(tenant_id,serial));
CREATE TABLE IF NOT EXISTS robot_capabilities (robot_id TEXT NOT NULL REFERENCES robots(id), name TEXT NOT NULL, revision INTEGER NOT NULL, schema_json TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(robot_id,name));
CREATE TABLE IF NOT EXISTS missions (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), robot_id TEXT NOT NULL REFERENCES robots(id), status TEXT NOT NULL, priority INTEGER NOT NULL, policy_version INTEGER NOT NULL, owner TEXT, attempt INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS mission_steps (id TEXT PRIMARY KEY, mission_id TEXT NOT NULL REFERENCES missions(id), ordinal INTEGER NOT NULL, action TEXT NOT NULL, payload_json TEXT NOT NULL, status TEXT NOT NULL, UNIQUE(mission_id,ordinal));
CREATE TABLE IF NOT EXISTS telemetry_events (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), robot_id TEXT NOT NULL REFERENCES robots(id), sequence INTEGER NOT NULL, kind TEXT NOT NULL, payload_json TEXT NOT NULL, recorded_at TEXT NOT NULL, UNIQUE(robot_id,sequence));
CREATE TABLE IF NOT EXISTS policies (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, revision INTEGER NOT NULL, expression TEXT NOT NULL, state TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(tenant_id,name,revision));
CREATE TABLE IF NOT EXISTS approvals (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), mission_id TEXT NOT NULL REFERENCES missions(id), policy_id TEXT NOT NULL REFERENCES policies(id), policy_revision INTEGER NOT NULL, decision TEXT NOT NULL, decided_by TEXT, decided_at TEXT);
CREATE TABLE IF NOT EXISTS handoffs (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), mission_id TEXT NOT NULL REFERENCES missions(id), operator_id TEXT NOT NULL REFERENCES users(id), lease_until TEXT NOT NULL, state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS alerts (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), robot_id TEXT NOT NULL REFERENCES robots(id), dedupe_key TEXT NOT NULL, severity TEXT NOT NULL, message TEXT NOT NULL, state TEXT NOT NULL, created_at TEXT NOT NULL, acknowledged_at TEXT, UNIQUE(tenant_id,dedupe_key));
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), actor_id TEXT, action TEXT NOT NULL, object_type TEXT NOT NULL, object_id TEXT NOT NULL, detail_json TEXT NOT NULL, occurred_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS outbox_jobs (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), topic TEXT NOT NULL, payload_json TEXT NOT NULL, state TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, available_at TEXT NOT NULL, last_error TEXT);
CREATE TABLE IF NOT EXISTS idempotency_keys (tenant_id TEXT NOT NULL REFERENCES tenants(id), key TEXT NOT NULL, resource_id TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(tenant_id,key));
CREATE INDEX IF NOT EXISTS idx_missions_queue ON missions(tenant_id,status,priority DESC,created_at);
CREATE INDEX IF NOT EXISTS idx_telemetry_robot_time ON telemetry_events(robot_id,recorded_at);
CREATE INDEX IF NOT EXISTS idx_alerts_state ON alerts(tenant_id,state,created_at);
